class Solution:
    def vowelStrings(self, words: list[str], queries: list[list[int]]) -> list[int]:
        vowels = set('aeiou')
        n = len(words)
        pref = [0] * (n + 1)
        for i, w in enumerate(words):
            is_v = 1 if w[0] in vowels and w[-1] in vowels else 0
            pref[i + 1] = pref[i] + is_v
        return [pref[r + 1] - pref[l] for l, r in queries]

class Solution {
public:
    std::vector<int> vowelStrings(std::vector<std::string>& words, std::vector<std::vector<int>>& queries) {
        auto is_vowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };
        int n = words.size();
        std::vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            bool ok = is_vowel(words[i].front()) && is_vowel(words[i].back());
            pref[i + 1] = pref[i] + (ok ? 1 : 0);
        }
        std::vector<int> ans(queries.size());
        for (size_t i = 0; i < queries.size(); ++i) {
            ans[i] = pref[queries[i][1] + 1] - pref[queries[i][0]];
        }
        return ans;
    }
};

class Solution {
    public int[] vowelStrings(String[] words, int[][] queries) {
        int n = words.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            String w = words[i];
            boolean ok = isVowel(w.charAt(0)) && isVowel(w.charAt(w.length() - 1));
            pref[i + 1] = pref[i] + (ok ? 1 : 0);
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = pref[queries[i][1] + 1] - pref[queries[i][0]];
        }
        return ans;
    }
    private boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}

var vowelStrings = function(words, queries) {
